・気温が上がると蒸発が進み、蒸気濃度が上がる。夏場に事故が増える物理的な理由がこれ
・タンクの通気管は、昼夜の温度差で気体の膨張収縮が起きてもタンクが変形しないための設備。三態と体積変化の話が法令側にそのまま出てくる
・固体のパラフィンやナフタレンのように、常温で昇華する物質は固体のままでも蒸気を出すため、固体だから安全とは言えない
・液体窒素やドライアイスの取り扱いで「気体になると体積が数百倍」になることも同じ原理

【図解】1リットルの液体が全部蒸気になったときのおおよその体積
　物質｜液1Lからの蒸気体積の目安｜現場での意味
