　氷を鍋に入れて弱火にかけ、温度計を差したまま観察すると、氷が溶けきるまで温度計はゼロ度から動きません。火を止めていないのに温度が上がらないのです。これは加えた熱が温度を上げるためではなく、氷の結晶をほどく仕事に全部使われているからです。この温度が融点です。
　同じことが沸騰でも起きます。水は100度で沸き始め、沸騰が続いているあいだは強火にしても温度計は100度のまま動きません。加えた熱は液体を蒸気に変える仕事に使われます。この温度が沸点です。
　危険物の世界では、この二つの温度が保管条件を決めます。沸点が低い物質は常温でも蒸気を出しやすく、引火の危険が高い。融点が高い物質は常温で固体なので第4類には該当しにくい。融点・沸点は「その物質が常温でどの姿でいるか」を決める番号札だと考えてください。

━━━━━━━━━━━━━━━━━━━━━━
