　風がある｜蒸気を運び去り平衡に達しない｜屋外の給油作業でも油断できない
　圧力が低い｜飛び出しを妨げる力が弱い｜減圧下では蒸発が加速
　⚠「容器のふたを開けておけば蒸発して危険が減る」は誤り。蒸気が広がるだけで危険は増す

・液体の量そのものは蒸発の速さに直接は関係しない。関係するのは表面積★
