　危険物では、溶解性が消火方法を左右します。エタノールやアセトンのように水と自由に混ざる（水溶性の）危険物には、ふつうの泡消火剤を使うと泡が壊されてしまうため、水溶性液体用泡消火剤（耐アルコール泡）を使わなければなりません。一方ガソリンや灯油は水に溶けないので、水をかけると浮いて広がります。溶けるか溶けないかは、そのまま危険物の分類（水溶性・非水溶性）と指定数量に反映されています。

