　火災はまさに熱が移動して広がる現象です。燃えている場所から周囲の可燃物へ熱が伝わり、その可燃物が発火点や引火点に達して新たに燃え出す。延焼のしくみは熱の移動の三つの形で説明できます。逆に、この三つを断てば火災は広がりません。消火や防火の設計はここから出発します。

