　危険物の世界では、この区別が「危険物であり続けるかどうか」を決めます。ガソリンが蒸発しても物理変化なのでガソリンのまま、蒸気も危険物です。しかしガソリンが燃焼すれば化学変化なので、二酸化炭素と水という別物になり、もはや危険物ではありません。事故対応でも、蒸発した蒸気は依然として危険なのか、それとも反応して無害化したのかで、判断がまったく変わります。

