　化学反応式は、左に反応する物質、右にできる物質を書き、矢印でつないだものです。ただし単に書けばよいのではなく、左右で原子の種類ごとの個数を必ず一致させなければなりません。原子は反応で生まれも消えもしないからです。この数合わせを係数合わせ（つり合わせ）といいます。
　危険物では、燃焼の反応式が書ければ、必要な酸素量、発生する二酸化炭素と水の量、それらの体積が計算できます。「ガソリン1リットルの燃焼に必要な空気は何立方メートルか」といった実務的な見積もりの出発点が、この反応式です。式が書ければ量が出る、量が出れば換気や消火の設計ができる、という順序で理解してください。

