・アボガドロの法則：同温同圧同体積の気体には同数の分子が含まれる★
・これらを統合したのが現在の化学反応式であり、係数がモル比かつ気体の体積比を表す根拠になっている★

【図解】主な法則の整理
　法則｜提唱者｜内容
　質量保存の法則｜ラボアジエ｜反応前後で質量の総和は不変★
　定比例の法則｜プルースト｜化合物の元素質量比は一定★
　倍数比例の法則｜ドルトン｜複数化合物で質量が簡単な整数比★
　気体反応の法則｜ゲーリュサック｜気体の体積比が簡単な整数比★
　アボガドロの法則｜アボガドロ｜同温同圧同体積で同数の分子★
