・第5類危険物は自己反応性物質で、分解時に大量の熱と気体を出す。酸素の供給がなくても燃焼が進む★
・混合危険：酸化性の物質（第1類・第6類）と可燃物を混ぜると発熱・発火する。混載や混合の禁止はこのため★

