━━━━━━━━━━━━━━━━━━━━━━
・第4類危険物の発熱量は、おおむね1kgあたり40MJから45MJ前後で、木材の2倍以上ある★
・同じ体積なら、比重の大きい重油のほうが総発熱量は大きい
・ただし火災の危険度は発熱量だけでは決まらない。引火点が低く蒸気が出やすいほど着火しやすい★
・つまり「燃えやすさ」は引火点と燃焼範囲で、「燃えたときの激しさ」は発熱量で判断する。二つの軸を分けて考える★
