　反応が起こるには、分子どうしが十分なエネルギーを持って衝突する必要があります。だから、衝突の回数を増やすか、衝突1回あたりの成功率を上げれば反応は速くなります。温度、濃度、表面積、触媒、圧力といった条件はすべて、この二つのどちらかに効いています。
　危険物では、反応速度は火災の激しさそのものです。ゆっくりなら酸化、速ければ燃焼、きわめて速ければ爆発。粉じん爆発が起こるのは、表面積が桁違いに大きくなって反応速度が跳ね上がるからです。

