　水溶液が酸性かアルカリ性かを、7を真ん中にした0から14の数字で表したものがpH（水素イオン指数）です。7が中性、7より小さければ酸性、大きければアルカリ性です。
　この数字は水素イオン濃度の対数から決まるので、1違うと濃度は10倍違います。pH3とpH5では、水素イオンの濃さは100倍も差があります。「pH4はpH5より1だけ酸性が強い」ではなく「10倍強い」と読むのが正しい理解です。
　危険物では、タンクや配管の腐食、こぼれた薬品の中和処理、排水の管理などでpHを扱います。金属は強い酸性でも強いアルカリ性でも腐食が進みやすく、中性付近が最も安定です。数字ひとつで危険の度合いを判断できる、実用的な指標です。

