・もとの酸と塩基の強弱で決まる。強いほうの性質が残ると考える★

【図解】もとの組合せと液性
　もとの酸｜もとの塩基｜水溶液の液性｜例
　強酸｜強塩基｜中性｜塩化ナトリウム★
　弱酸｜強塩基｜アルカリ性｜炭酸ナトリウム、酢酸ナトリウム★
