・こぼれた酸の処理には重曹や消石灰が使われる。反応がおだやかで扱いやすい★

【図解】粉末消火剤と塩
　薬剤の種類｜主成分｜適応火災
　粉末ナトリウム塩｜炭酸水素ナトリウム｜油火災と電気火災★
　粉末カリウム塩｜炭酸水素カリウム｜油火災と電気火災
　粉末りん酸塩（ABC）｜りん酸二水素アンモニウム｜普通・油・電気すべて★
