・第1類（酸化性固体）と第6類（酸化性液体）は、それ自身は燃えないが他の物質を酸化させる。可燃物と混ぜると発火の恐れがある★
・第2類（可燃性固体）、第4類（引火性液体）は酸化される側、つまり還元剤として働く★
・混載や貯蔵の制限は、酸化される側とさせる側を近づけない、という原則に基づく★
・窒息消火は、酸化される相手（酸素）を断つことで酸化還元反応を止める操作である★

