・自然発火：ゆるやかな酸化の熱が逃げずにたまり、ついに発火点に達したもの★
・爆発：きわめて速い酸化。圧力波をともなう
・つまり同じ酸化反応でも、速さと熱の逃げ方だけで現象の名前が変わる★
・危険物の管理は、酸化の速さを遅くし、出た熱を逃がすことに尽きる★

