　酸素も水素も関与しない反応では、どちらが酸化されたのか一見して分かりません。そこで、原子ごとに「電子をどれだけ持っているか」を示す仮想の数字を割り当てます。これが酸化数です。反応の前後で酸化数が増えていればその原子は酸化された、減っていれば還元されたと判定できます。
　危険物の試験では複雑な酸化数計算は問われませんが、酸化数の基本ルールを知っていると、酸化剤と還元剤の判定が確実になります。とくに硫黄や窒素、マンガンのように複数の酸化数をとる元素では、酸化数を見れば「まだ酸化される余地があるか」「すでに酸化されきっているか」が分かります。

